import { test, expect, Page, Locator } from '@playwright/test';

const USER_A_HEADERS = { 'x-browser-fingerprint': 'qa-v2-user-a-001' };
const USER_B_HEADERS = { 'x-browser-fingerprint': 'qa-v2-user-b-002' };

// Valid 1x1 PNG binary fixture (self-contained, no external file dependency)
const TINY_PNG_BASE64 =
  'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=';
const TINY_PNG_BUFFER = Buffer.from(TINY_PNG_BASE64, 'base64');

// Safe placeholder API key strings without any secret-scanning prefix patterns
const PLACEHOLDER_RESEND_KEY_API = 'YOUR_RESEND_API_KEY_PLACEHOLDER_9876';
const PLACEHOLDER_RESEND_KEY_UI = 'YOUR_RESEND_API_KEY_PLACEHOLDER_4321';

const DEFAULT_VALID_SETTINGS = {
  resend_from_email: 'noreply@example.com',
  site_name: '新版图文社区',
  otp_expiry_minutes: 10,
  max_images_per_post: 4,
};

/**
 * Resiliently locates the post card containing markerText inside the main feed region,
 * avoiding collisions with right-sidebar hot_posts widgets and supporting both semantic
 * <article> tags and component-library <div> cards.
 */
async function findPostCard(page: Page, markerText: string): Promise<Locator> {
  await expect(page.getByText(markerText).first()).toBeVisible();
  const mainCount = await page.getByRole('main').count();
  const mainScope = mainCount > 0 ? page.getByRole('main').first() : page;
  await expect(mainScope.getByText(markerText).first()).toBeVisible();

  const semanticCard = mainScope
    .locator('article, [data-testid="post-card"], .post-card')
    .filter({ hasText: markerText })
    .first();
  if ((await semanticCard.count()) > 0) {
    return semanticCard;
  }

  const actionButtonLocator = page.getByRole('button', {
    name: /点赞|喜欢|赞|like|转发|转帖|repost|retweet|评论|回复|comment|reply/i,
  });
  const cardWithActions = mainScope
    .locator('article, section, li, div')
    .filter({ hasText: markerText })
    .filter({ has: actionButtonLocator })
    .last();
  if ((await cardWithActions.count()) > 0) {
    return cardWithActions;
  }

  const cardWithAnyButton = mainScope
    .locator('article, section, li, div')
    .filter({ hasText: markerText })
    .filter({ has: page.locator('button') })
    .last();
  if ((await cardWithAnyButton.count()) > 0) {
    return cardWithAnyButton;
  }

  return mainScope.locator('article, section, li, div').filter({ hasText: markerText }).last();
}

test.describe('Community V2: Media Upload & Image-Text Posts API', () => {
  test('POST /api/v1/media/upload & GET /api/v1/media/:id validate auth, MIME, size, traversal, and concurrency', async ({
    request,
  }) => {
    // 1. Unauthenticated upload rejected
    const unauthRes = await request.post('/api/v1/media/upload', {
      data: {
        data_url: `data:image/png;base64,${TINY_PNG_BASE64}`,
        filename: 'unauth.png',
      },
    });
    expect(unauthRes.status()).toBe(401);
    expect(JSON.stringify(await unauthRes.json())).toContain('401_UNAUTHORIZED');

    // 2. Non-image / SVG MIME rejected via multipart
    const invalidMimeRes = await request.post('/api/v1/media/upload', {
      headers: USER_A_HEADERS,
      multipart: {
        file: {
          name: 'malicious.svg',
          mimeType: 'image/svg+xml',
          buffer: Buffer.from('<svg xmlns="http://www.w3.org/2000/svg"><script>alert(1)</script></svg>'),
        },
      },
    });
    expect(invalidMimeRes.status()).toBe(400);
    expect(JSON.stringify(await invalidMimeRes.json())).toContain('400_INVALID_MEDIA');

    // 3. Disallowed MIME & malformed data_url rejected via JSON channel
    for (const badPayload of [
      {
        data_url: `data:text/html;base64,${Buffer.from('<script>alert(1)</script>').toString('base64')}`,
        filename: 'xss.html',
      },
      {
        data_url: `data:image/svg+xml;base64,${Buffer.from('<svg></svg>').toString('base64')}`,
        filename: 'vector.svg',
      },
      {
        data_url: 'not-a-valid-data-url',
        filename: 'broken.png',
      },
    ]) {
      const badJsonUpload = await request.post('/api/v1/media/upload', {
        headers: USER_A_HEADERS,
        data: badPayload,
      });
      expect(badJsonUpload.status()).toBe(400);
      expect(JSON.stringify(await badJsonUpload.json())).toContain('400_INVALID_MEDIA');
    }

    // 4. Oversized payload (11MB, exceeds 2MB/5MB/10MB caps) rejected with 413
    const oversizedBuffer = Buffer.alloc(11 * 1024 * 1024, 0);
    TINY_PNG_BUFFER.copy(oversizedBuffer);
    const tooLargeRes = await request.post('/api/v1/media/upload', {
      headers: USER_A_HEADERS,
      multipart: {
        file: {
          name: 'too-large.png',
          mimeType: 'image/png',
          buffer: oversizedBuffer,
        },
      },
    });
    expect(tooLargeRes.status()).toBe(413);
    expect(JSON.stringify(await tooLargeRes.json())).toContain('413_MEDIA_TOO_LARGE');

    // 5. Valid multipart PNG upload
    const multipartRes = await request.post('/api/v1/media/upload', {
      headers: USER_A_HEADERS,
      multipart: {
        file: {
          name: 'sample.png',
          mimeType: 'image/png',
          buffer: TINY_PNG_BUFFER,
        },
      },
    });
    expect([200, 201]).toContain(multipartRes.status());
    const multipartBody = await multipartRes.json();
    expect(typeof multipartBody.id).toBe('string');
    expect(multipartBody.id.length).toBeGreaterThan(0);
    expect(multipartBody.url).toBe(`/api/v1/media/${multipartBody.id}`);
    expect(multipartBody.mime_type).toBe('image/png');
    expect(multipartBody.size_bytes).toBeGreaterThan(0);

    // 6. Valid JSON data_url upload
    const jsonUploadRes = await request.post('/api/v1/media/upload', {
      headers: USER_A_HEADERS,
      data: {
        data_url: `data:image/png;base64,${TINY_PNG_BASE64}`,
        filename: 'sample-data-url.png',
      },
    });
    expect([200, 201]).toContain(jsonUploadRes.status());
    const jsonUploadBody = await jsonUploadRes.json();
    expect(typeof jsonUploadBody.id).toBe('string');
    expect(jsonUploadBody.url).toBe(`/api/v1/media/${jsonUploadBody.id}`);

    // 7. Concurrent uploads produce unique IDs with zero collisions
    const concurrentUploads = await Promise.all(
      Array.from({ length: 4 }, (_, idx) =>
        request.post('/api/v1/media/upload', {
          headers: USER_A_HEADERS,
          data: {
            data_url: `data:image/png;base64,${TINY_PNG_BASE64}`,
            filename: `concurrent-${idx}.png`,
          },
        })
      )
    );
    const concurrentIds = new Set<string>();
    for (const res of concurrentUploads) {
      expect([200, 201]).toContain(res.status());
      const body = await res.json();
      expect(typeof body.id).toBe('string');
      concurrentIds.add(body.id);
    }
    expect(concurrentIds.size).toBe(4);

    // 8. GET /api/v1/media/:id serves binary image with security headers
    const fetchMediaRes = await request.get(multipartBody.url);
    expect(fetchMediaRes.status()).toBe(200);
    expect(fetchMediaRes.headers()['content-type']).toContain('image/png');
    expect(fetchMediaRes.headers()['x-content-type-options']).toContain('nosniff');
    expect(fetchMediaRes.headers()['cache-control']).toBeTruthy();
    const fetchedBytes = await fetchMediaRes.body();
    expect(fetchedBytes.byteLength).toBeGreaterThan(0);

    // 9. Non-existent media ID and path traversal attempts are safely rejected
    const missingMediaRes = await request.get('/api/v1/media/non-existent-media-id-99999');
    expect(missingMediaRes.status()).toBe(404);
    expect(JSON.stringify(await missingMediaRes.json())).toContain('404_MEDIA_NOT_FOUND');

    const traversalRes = await request.get('/api/v1/media/..%2F..%2Fpackage.json');
    expect([400, 404]).toContain(traversalRes.status());
  });

  test('POST /api/v1/posts supports image-only and multi-image posts while rejecting empty or invalid media', async ({
    request,
  }) => {
    const uploadedIds: string[] = [];
    for (let i = 0; i < 5; i++) {
      const res = await request.post('/api/v1/media/upload', {
        headers: USER_A_HEADERS,
        data: {
          data_url: `data:image/png;base64,${TINY_PNG_BASE64}`,
          filename: `img-${i}.png`,
        },
      });
      expect([200, 201]).toContain(res.status());
      const body = await res.json();
      uploadedIds.push(body.id);
    }

    // Empty content with no media rejected
    const emptyRes = await request.post('/api/v1/posts', {
      headers: USER_A_HEADERS,
      data: { content: '   ', media_ids: [] },
    });
    expect(emptyRes.status()).toBe(400);
    expect(JSON.stringify(await emptyRes.json())).toContain('400_INVALID_CONTENT');

    // More than 4 images rejected
    const tooManyImagesRes = await request.post('/api/v1/posts', {
      headers: USER_A_HEADERS,
      data: { content: 'Too many images', media_ids: uploadedIds },
    });
    expect(tooManyImagesRes.status()).toBe(400);
    expect(JSON.stringify(await tooManyImagesRes.json())).toContain('400_INVALID_MEDIA');

    // Non-existent media_id rejected
    const badMediaRes = await request.post('/api/v1/posts', {
      headers: USER_A_HEADERS,
      data: { content: 'Bad media ref', media_ids: ['non-existent-media-xyz'] },
    });
    expect(badMediaRes.status()).toBe(400);
    expect(JSON.stringify(await badMediaRes.json())).toContain('400_INVALID_MEDIA');

    // Image-only post succeeds
    const imageOnlyRes = await request.post('/api/v1/posts', {
      headers: USER_A_HEADERS,
      data: { content: '', media_ids: [uploadedIds[0]] },
    });
    expect([200, 201]).toContain(imageOnlyRes.status());
    const imageOnlyBody = await imageOnlyRes.json();
    expect(typeof imageOnlyBody.id).toBe('string');
    expect(Array.isArray(imageOnlyBody.images)).toBe(true);
    expect(imageOnlyBody.images.length).toBe(1);
    expect(imageOnlyBody.images[0].id).toBe(uploadedIds[0]);

    // Mixed text + 2 images post succeeds and appears in feed
    const mixedMarker = `MixedImagePost-${Date.now()}`;
    const mixedRes = await request.post('/api/v1/posts', {
      headers: USER_A_HEADERS,
      data: { content: mixedMarker, media_ids: [uploadedIds[1], uploadedIds[2]] },
    });
    expect([200, 201]).toContain(mixedRes.status());
    const mixedBody = await mixedRes.json();
    expect(mixedBody.images.length).toBe(2);

    // Verify GET /api/v1/feed search & enriched schema
    const feedRes = await request.get('/api/v1/feed', {
      headers: USER_A_HEADERS,
      params: { q: mixedMarker, sort: 'latest', limit: 10 },
    });
    expect(feedRes.status()).toBe(200);
    const feedBody = await feedRes.json();
    const found = feedBody.posts.find((p: { id: string }) => p.id === mixedBody.id);
    expect(found).toBeTruthy();
    expect(typeof found.author_name).toBe('string');
    expect(Array.isArray(found.images)).toBe(true);
    expect(found.images.length).toBe(2);
    expect(typeof found.clicks_count).toBe('number');
    expect(typeof found.views_count).toBe('number');
    expect(typeof found.likes_count).toBe('number');
    expect(typeof found.reposts_count).toBe('number');
    expect(typeof found.comments_count).toBe('number');
    expect(typeof found.user_liked).toBe('boolean');
    expect(typeof found.user_reposted).toBe('boolean');
  });
});

test.describe('Community V2: Real 4D Stats, Atomic Concurrency & Overview API', () => {
  test('Like, repost, concurrent atomic clicks, comments, and stats overview reflect persisted real counts', async ({
    request,
  }) => {
    const overviewBeforeRes = await request.get('/api/v1/stats/overview');
    expect(overviewBeforeRes.status()).toBe(200);
    const overviewBefore = await overviewBeforeRes.json();
    expect(typeof overviewBefore.totals.posts).toBe('number');
    expect(typeof overviewBefore.totals.likes).toBe('number');
    expect(typeof overviewBefore.totals.reposts).toBe('number');
    expect(typeof overviewBefore.totals.clicks).toBe('number');
    expect(typeof overviewBefore.totals.comments).toBe('number');

    // Seed target post
    const uniqueContent = `StatsTarget-${Date.now()}`;
    const createRes = await request.post('/api/v1/posts', {
      headers: USER_A_HEADERS,
      data: { content: uniqueContent },
    });
    expect([200, 201]).toContain(createRes.status());
    const { id: postId } = await createRes.json();

    // Auth and 404 checks
    expect((await request.post(`/api/v1/posts/${postId}/like`)).status()).toBe(401);
    expect((await request.post(`/api/v1/posts/${postId}/repost`)).status()).toBe(401);
    expect(
      (await request.post('/api/v1/posts/non-existent-post-999/like', { headers: USER_A_HEADERS })).status()
    ).toBe(404);
    expect(
      (await request.post('/api/v1/posts/non-existent-post-999/repost', { headers: USER_A_HEADERS })).status()
    ).toBe(404);
    expect((await request.post('/api/v1/posts/non-existent-post-999/click')).status()).toBe(404);

    // Like toggle across two users
    const likeA1 = await request.post(`/api/v1/posts/${postId}/like`, { headers: USER_A_HEADERS });
    expect(likeA1.status()).toBe(200);
    expect(await likeA1.json()).toMatchObject({ post_id: postId, liked: true, likes_count: 1 });

    const likeB1 = await request.post(`/api/v1/posts/${postId}/like`, { headers: USER_B_HEADERS });
    expect(likeB1.status()).toBe(200);
    expect(await likeB1.json()).toMatchObject({ post_id: postId, liked: true, likes_count: 2 });

    const likeA2 = await request.post(`/api/v1/posts/${postId}/like`, { headers: USER_A_HEADERS });
    expect(likeA2.status()).toBe(200);
    expect(await likeA2.json()).toMatchObject({ post_id: postId, liked: false, likes_count: 1 });

    // Repost toggle
    const repostA1 = await request.post(`/api/v1/posts/${postId}/repost`, { headers: USER_A_HEADERS });
    expect(repostA1.status()).toBe(200);
    expect(await repostA1.json()).toMatchObject({ post_id: postId, reposted: true, reposts_count: 1 });

    const repostA2 = await request.post(`/api/v1/posts/${postId}/repost`, { headers: USER_A_HEADERS });
    expect(repostA2.status()).toBe(200);
    expect(await repostA2.json()).toMatchObject({ post_id: postId, reposted: false, reposts_count: 0 });

    const repostB1 = await request.post(`/api/v1/posts/${postId}/repost`, { headers: USER_B_HEADERS });
    expect(repostB1.status()).toBe(200);
    expect(await repostB1.json()).toMatchObject({ post_id: postId, reposted: true, reposts_count: 1 });

    // Concurrent atomic click increments (5 simultaneous clicks -> exact total 5)
    const concurrentClicks = await Promise.all(
      Array.from({ length: 5 }, () => request.post(`/api/v1/posts/${postId}/click`))
    );
    for (const res of concurrentClicks) {
      expect(res.status()).toBe(200);
      const body = await res.json();
      expect(body.post_id).toBe(postId);
      expect(typeof body.clicks_count).toBe('number');
      expect(typeof body.views_count).toBe('number');
    }

    // Comment increment
    const commentRes = await request.post(`/api/v1/posts/${postId}/comments`, {
      headers: USER_A_HEADERS,
      data: { content: 'Counting real comments' },
    });
    expect([200, 201]).toContain(commentRes.status());

    // Verify feed reflects exact stats and per-user interaction flags
    const feedForBRes = await request.get('/api/v1/feed', {
      headers: USER_B_HEADERS,
      params: { q: uniqueContent, limit: 10 },
    });
    expect(feedForBRes.status()).toBe(200);
    const feedForB = await feedForBRes.json();
    const targetInFeed = feedForB.posts.find((p: { id: string }) => p.id === postId);
    expect(targetInFeed).toBeTruthy();
    expect(targetInFeed.likes_count).toBe(1);
    expect(targetInFeed.reposts_count).toBe(1);
    expect(targetInFeed.clicks_count).toBe(5);
    expect(targetInFeed.views_count).toBe(5);
    expect(targetInFeed.comments_count).toBe(1);
    expect(targetInFeed.user_liked).toBe(true);
    expect(targetInFeed.user_reposted).toBe(true);

    // Verify hot sort returns 200
    const hotFeedRes = await request.get('/api/v1/feed', { params: { sort: 'hot', limit: 10 } });
    expect(hotFeedRes.status()).toBe(200);
    const hotFeed = await hotFeedRes.json();
    expect(Array.isArray(hotFeed.posts)).toBe(true);

    // Verify overview reflects real DB increments
    const overviewAfterRes = await request.get('/api/v1/stats/overview');
    expect(overviewAfterRes.status()).toBe(200);
    const overviewAfter = await overviewAfterRes.json();
    expect(overviewAfter.totals.posts).toBeGreaterThanOrEqual(overviewBefore.totals.posts + 1);
    expect(overviewAfter.totals.likes).toBeGreaterThanOrEqual(overviewBefore.totals.likes + 1);
    expect(overviewAfter.totals.reposts).toBeGreaterThanOrEqual(overviewBefore.totals.reposts + 1);
    expect(overviewAfter.totals.clicks).toBeGreaterThanOrEqual(overviewBefore.totals.clicks + 5);
    expect(overviewAfter.totals.comments).toBeGreaterThanOrEqual(overviewBefore.totals.comments + 1);
    expect(Array.isArray(overviewAfter.hot_posts)).toBe(true);
  });
});

test.describe('Community V2: Email OTP Auth API Contracts', () => {
  test('Auth routes validate email format, malformed codes, invalid tokens, /me dual auth, and logout', async ({
    request,
  }) => {
    const invalidEmailRes = await request.post('/api/v1/auth/send-code', {
      data: { email: 'not-a-valid-email' },
    });
    expect(invalidEmailRes.status()).toBe(400);
    expect(JSON.stringify(await invalidEmailRes.json())).toContain('400_INVALID_EMAIL');

    // Invalid / malformed verification codes rejected
    for (const badCode of ['000000', '123', 'abcdef', '']) {
      const invalidCodeRes = await request.post('/api/v1/auth/verify-code', {
        data: { email: 'nobody@example.com', code: badCode },
      });
      expect(invalidCodeRes.status()).toBe(400);
      expect(JSON.stringify(await invalidCodeRes.json())).toContain('400_INVALID_CODE');
    }

    // Missing or bogus auth rejected on /api/v1/auth/me
    const unauthMeRes = await request.get('/api/v1/auth/me');
    expect(unauthMeRes.status()).toBe(401);
    expect(JSON.stringify(await unauthMeRes.json())).toContain('401_UNAUTHORIZED');

    const forgedMeRes = await request.get('/api/v1/auth/me', {
      headers: { Authorization: 'Bearer invalid-session-token-placeholder' },
    });
    expect(forgedMeRes.status()).toBe(401);
    expect(JSON.stringify(await forgedMeRes.json())).toContain('401_UNAUTHORIZED');

    const fpMeRes = await request.get('/api/v1/auth/me', { headers: USER_A_HEADERS });
    expect(fpMeRes.status()).toBe(200);
    const fpMeBody = await fpMeRes.json();
    expect(fpMeBody.authenticated).toBe(true);
    expect(fpMeBody.auth_type).toBe('fingerprint');
    expect(typeof fpMeBody.user?.id).toBe('string');

    const logoutRes = await request.post('/api/v1/auth/logout');
    expect(logoutRes.status()).toBe(200);
    expect(await logoutRes.json()).toMatchObject({ success: true });
  });
});

test.describe('Community V2 Web E2E: Image-Text Feed, Real Stats & Email Login', () => {
  test('Public community page exposes no /admin entry links or buttons and removes legacy mock widgets', async ({
    page,
  }) => {
    await page.goto('/');
    const feedRegion = page.getByTestId('feed-list').or(page.getByRole('main')).first();
    await expect(feedRegion).toBeVisible();

    // Strictly verify hidden admin rule: no link or navigation button pointing to admin console
    await expect(page.locator('a[href="/admin"], a[href^="/admin/"]')).toHaveCount(0);
    await expect(page.getByRole('link', { name: /管理后台|管理员|后台管理|admin/i })).toHaveCount(0);
    await expect(
      page.getByRole('button', { name: /管理后台|管理员入口|后台管理|admin\s*(panel|console|login|dashboard)/i })
    ).toHaveCount(0);

    // Verify legacy hardcoded mock cards are removed
    await expect(page.getByText('订阅 Premium')).toHaveCount(0);
    await expect(page.getByText('#Awwwards2026')).toHaveCount(0);
    await expect(page.getByText('48.2K 动态')).toHaveCount(0);
  });

  test('User uploads image with text, safely escapes XSS, and persists image post across reload', async ({
    page,
  }) => {
    let xssAlertTriggered = false;
    page.on('dialog', async (dialog) => {
      xssAlertTriggered = true;
      await dialog.dismiss();
    });

    await page.goto('/');

    const mainRegion = page.getByRole('main').first();
    const hasMain = (await page.getByRole('main').count()) > 0;
    const rootScope = hasMain ? mainRegion : page;

    const postInput = rootScope
      .getByRole('textbox', { name: /发帖|动态|说点什么|分享|写点什么|post|content/i })
      .or(rootScope.locator('textarea'))
      .first();
    await expect(postInput).toBeVisible();

    // Scope submit button & file input to the enclosing composer form (or main region) so sidebar buttons are never clicked
    const composerForm = page.locator('form').filter({ has: postInput }).first();
    const composerScope = (await composerForm.count()) > 0 ? composerForm : rootScope;

    const publishButton = composerScope
      .getByRole('button', { name: /发布|发帖|发送|post|publish/i })
      .first();
    const fileInput = composerScope.locator('input[type="file"]').first();

    await expect(publishButton).toBeVisible();
    await expect(fileInput).toBeAttached();

    const uniqueCaption = `<img src=x onerror="window.__v2Xss=true;alert(1)"> ImagePostE2E-${Date.now()}`;
    await postInput.fill(uniqueCaption);

    // Support both eager upload-on-select and lazy upload-on-submit architectures
    const eagerUploadPromise = page
      .waitForResponse(
        (res) => res.url().includes('/api/v1/media/upload') && res.request().method() === 'POST',
        { timeout: 2500 }
      )
      .catch(() => null);

    await fileInput.setInputFiles({
      name: 'community-photo.png',
      mimeType: 'image/png',
      buffer: TINY_PNG_BUFFER,
    });
    await eagerUploadPromise;
    await expect(publishButton).toBeEnabled();

    const postDonePromise = page.waitForResponse(
      (res) => res.url().includes('/api/v1/posts') && res.request().method() === 'POST'
    );
    await publishButton.click();
    const postResp = await postDonePromise;
    expect([200, 201]).toContain(postResp.status());

    const markerText = uniqueCaption.split(' ').pop() || uniqueCaption;
    const postCard = await findPostCard(page, markerText);
    await expect(postCard).toBeVisible();

    // Verify XSS payload did not execute
    expect(xssAlertTriggered).toBe(false);
    const xssFlag = await page.evaluate(() => (window as unknown as { __v2Xss?: boolean }).__v2Xss);
    expect(xssFlag).toBeUndefined();

    // Verify uploaded image renders with real loaded dimensions
    const renderedImg = postCard.locator('img[src*="/api/v1/media/"]').first();
    await expect(renderedImg).toBeVisible();
    await expect
      .poll(async () => renderedImg.evaluate((el: HTMLImageElement) => el.naturalWidth))
      .toBeGreaterThan(0);

    // Reload and verify image-text post persistence
    await page.reload();
    const reloadedCard = await findPostCard(page, markerText);
    await expect(reloadedCard).toBeVisible();
    const reloadedImg = reloadedCard.locator('img[src*="/api/v1/media/"]').first();
    await expect(reloadedImg).toBeVisible();
    await expect
      .poll(async () => reloadedImg.evaluate((el: HTMLImageElement) => el.naturalWidth))
      .toBeGreaterThan(0);
  });

  test('User likes, reposts, and comments on a post with real backend persistence after reload', async ({
    page,
    request,
  }) => {
    const seedText = `InteractiveStatsE2E-${Date.now()}`;
    const createRes = await request.post('/api/v1/posts', {
      headers: USER_A_HEADERS,
      data: { content: seedText },
